    second = make_executor(ops, journal, config).execute(
        [payment_proposal()], Inventory(ops)
    )
    assert second.actions[0].state == ActionState.UNKNOWN
    assert len(server.writes["hotel_vouchers"]) == 1, "the voucher stands"


